 static readonly Color Cyan=new(.05f,.85f,1), Pink=new(1,.05f,.45f);
 static Material Mat(string name,Color color,float glow=0,float metallic=.3f){var path=Root+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",.6f);if(glow>0){m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;m.SetColor("_EmissionColor",color*glow);m.EnableKeyword("_EMISSION");}EditorUtility.SetDirty(m);return m;}
 static GameObject Node(string name,Transform parent=null){var g=new GameObject(name);if(parent)g.transform.SetParent(parent,false);return g;}
 static GameObject Mesh(string name,Transform parent,Vector3 pos,Vector3 scale,Material mat,PrimitiveType primitive=PrimitiveType.Cube,bool collider=false){var g=GameObject.CreatePrimitive(primitive);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static Light Lamp(string name,Transform parent,Vector3 pos,Color color,float intensity,float range,LightType type=LightType.Point){var g=Node(name,parent);g.transform.localPosition=pos;var l=g.AddComponent<Light>();l.type=type;l.color=color;l.intensity=intensity;l.range=range;l.shadows=LightShadows.None;return l;}
 static GameObject SavePrefab(GameObject g,string name){var prefab=PrefabUtility.SaveAsPrefabAsset(g,Root+"Prefabs/"+name+".prefab");UnityEngine.Object.DestroyImmediate(g);return prefab;}
 static ParticleSystem Particle(string name,Transform parent,float speed,float lifetime,float size,Material material,bool continuous=false){var g=Node(name,parent);var p=g.AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.playOnAwake=continuous;main.loop=continuous;main.duration=3;main.startLifetime=lifetime;main.startSpeed=speed;main.startSize=size;main.maxParticles=250;main.simulationSpace=ParticleSystemSimulationSpace.World;main.startColor=Cyan;var em=p.emission;em.enabled=continuous;em.rateOverTime=continuous?24:0;var shape=p.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.1f;var col=p.colorOverLifetime;col.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(1,0),new GradientAlphaKey(0,1)});col.color=gradient;var sizeLife=p.sizeOverLifetime;sizeLife.enabled=true;sizeLife.size=new ParticleSystem.MinMaxCurve(1,AnimationCurve.Linear(0,1,1,0));g.GetComponent<ParticleSystemRenderer>().sharedMaterial=material;return p;}
