 settings=AssetDatabase.LoadAssetAtPath<RunnerSettings>(Root+"Settings/RunnerSettings.asset");if(!settings){settings=ScriptableObject.CreateInstance<RunnerSettings>();AssetDatabase.CreateAsset(settings,Root+"Settings/RunnerSettings.asset");}
 asphalt=Mat("Asphalt",new Color(.035f,.045f,.075f),0,.2f);metal=Mat("Barrier",new Color(.12f,.16f,.23f),0,.7f);cyan=Mat("Neon Cyan",Cyan,5);pink=Mat("Neon Magenta",Pink,4);gold=Mat("Coin Gold",new Color(1,.65f,.05f),2);green=Mat("Fuel Green",new Color(.08f,1,.4f),2);glass=Mat("Tinted Glass",new Color(.025f,.12f,.19f),.25f,.85f);white=Mat("Headlight",new Color(.7f,.9f,1),7);red=Mat("Tail Light",new Color(1,.02f,.06f),5);playerPaint=Mat("Player Azure",new Color(.04f,.34f,.55f),.1f,.8f);trafficPaint=Mat("Traffic Coral",new Color(.65f,.055f,.15f),.1f,.65f);black=Mat("Rubber",new Color(.015f,.02f,.03f),0,0);
 particleMat=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/Particles.mat");if(!particleMat){particleMat=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));particleMat.SetColor("_BaseColor",Color.white);AssetDatabase.CreateAsset(particleMat,Root+"Materials/Particles.mat");}
 CreateInput();CreateAudio();
 var road=SavePrefab(CreateRoad(),"RoadSegment");var player=SavePrefab(CreateCar("PlayerCar",playerPaint,true),"PlayerCar");
 var stationary=CreateCar("StationaryCarObstacle",trafficPaint,false);stationary.AddComponent<StationaryCarObstacle>();stationary.AddComponent<PooledObject>();var statPrefab=SavePrefab(stationary,"StationaryCarObstacle");
 var moving=CreateCar("MovingCarObstacle",Mat("Traffic Violet",new Color(.4f,.08f,.7f),.15f),false);moving.AddComponent<MovingCarObstacle>();moving.AddComponent<PooledObject>();var movingPrefab=SavePrefab(moving,"MovingCarObstacle");
 var coin=Node("CoinCollectible");coin.AddComponent<PooledObject>();coin.AddComponent<CoinCollectible>();var coinMesh=Mesh("Coin",coin.transform,Vector3.zero,new Vector3(.72f,.12f,.72f),gold,PrimitiveType.Cylinder);coinMesh.transform.localRotation=Quaternion.Euler(90,0,0);Mesh("Core",coin.transform,new Vector3(0,0,.14f),new Vector3(.22f,.35f,.1f),white);var coinCol=coin.AddComponent<SphereCollider>();coinCol.radius=.72f;coinCol.isTrigger=true;var coinPrefab=SavePrefab(coin,"CoinCollectible");
 var fuel=Node("FuelCollectible");fuel.AddComponent<PooledObject>();fuel.AddComponent<FuelCollectible>();Mesh("Can",fuel.transform,Vector3.zero,new Vector3(.7f,.9f,.4f),green);Mesh("Handle",fuel.transform,new Vector3(0,.55f,0),new Vector3(.4f,.18f,.2f),metal);Mesh("Stripe",fuel.transform,new Vector3(0,0,-.22f),new Vector3(.12f,.55f,.03f),white);var fc=fuel.AddComponent<BoxCollider>();fc.size=new Vector3(1.15f,1.35f,.9f);fc.isTrigger=true;var fuelPrefab=SavePrefab(fuel,"FuelCollectible");
 foreach(bool isMenu in new[]{false,true})CreateScene(isMenu,player,road,statPrefab,movingPrefab,coinPrefab,fuelPrefab);
