 PlayerSettings.companyName="University Projects";PlayerSettings.productName="NEON HIGHWAY";PlayerSettings.defaultScreenWidth=1600;PlayerSettings.defaultScreenHeight=900;PlayerSettings.fullScreenMode=FullScreenMode.FullScreenWindow;PlayerSettings.runInBackground=true;
 PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Standalone,ScriptingImplementation.Mono2x);QualitySettings.vSyncCount=1;
 var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;rp.supportsHDR=true;EditorUtility.SetDirty(rp);foreach(var material in new[]{cyan,pink,gold,green,white,red}){material.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;material.EnableKeyword("_EMISSION");EditorUtility.SetDirty(material);}AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(Root+"Scenes/MainMenu.unity");File.WriteAllText("AUTHORING_RESULT.txt","All scenes, prefabs, materials, input, audio and references authored by Unity Editor.\n");Debug.Log("NEON_HIGHWAY_AUTHORING_COMPLETE");
