 static void CreateInput(){var asset=new InputActionAsset();var map=asset.AddActionMap("Driving");var left=map.AddAction("Left",InputActionType.Button);left.AddBinding("<Keyboard>/a");left.AddBinding("<Keyboard>/leftArrow");var right=map.AddAction("Right",InputActionType.Button);right.AddBinding("<Keyboard>/d");right.AddBinding("<Keyboard>/rightArrow");map.AddAction("Pause",InputActionType.Button,"<Keyboard>/escape");File.WriteAllText(Root+"Input/RunnerControls.inputactions",asset.ToJson());UnityEngine.Object.DestroyImmediate(asset);AssetDatabase.ImportAsset(Root+"Input/RunnerControls.inputactions",ImportAssetOptions.ForceSynchronousImport);input=AssetDatabase.LoadAssetAtPath<InputActionAsset>(Root+"Input/RunnerControls.inputactions");}
 static GameObject CreateCar(string name,Material paint,bool isPlayer){var car=Node(name);var visual=Node("Visual",car.transform).transform;
 Mesh("Chassis",visual,new Vector3(0,.55f,0),new Vector3(1.75f,.48f,3.7f),paint);Mesh("Hood",visual,new Vector3(0,.85f,1.05f),new Vector3(1.65f,.22f,1.35f),paint);Mesh("Cockpit",visual,new Vector3(0,1.05f,-.25f),new Vector3(1.38f,.62f,1.65f),glass);Mesh("Roof",visual,new Vector3(0,1.4f,-.35f),new Vector3(1.4f,.12f,1.1f),paint);Mesh("Front Splitter",visual,new Vector3(0,.29f,1.9f),new Vector3(1.9f,.12f,.3f),black);Mesh("Spoiler",visual,new Vector3(0,1.15f,-1.6f),new Vector3(1.95f,.12f,.38f),black);
 foreach(float x in new[]{-.91f,.91f})foreach(float z in new[]{-1.15f,1.1f}){var wheel=Mesh("Wheel",visual,new Vector3(x,.38f,z),new Vector3(.65f,.24f,.65f),black,PrimitiveType.Cylinder);wheel.transform.localRotation=Quaternion.Euler(0,0,90);var hub=Mesh("Hub",visual,new Vector3(x*1.14f,.38f,z),new Vector3(.35f,.025f,.35f),metal,PrimitiveType.Cylinder);hub.transform.localRotation=Quaternion.Euler(0,0,90);}
 foreach(float x in new[]{-.56f,.56f}){Mesh("Headlight",visual,new Vector3(x,.68f,1.87f),new Vector3(.45f,.12f,.06f),white);Mesh("Tail light",visual,new Vector3(x,.7f,-1.87f),new Vector3(.5f,.12f,.06f),red);}
 Mesh("Hood stripe",visual,new Vector3(0,.975f,1.1f),new Vector3(.16f,.02f,1.15f),isPlayer?cyan:white);
 var collider=car.AddComponent<BoxCollider>();collider.center=new Vector3(0,.7f,0);collider.size=new Vector3(1.7f,1.3f,3.6f);collider.isTrigger=!isPlayer;
 if(isPlayer){var rb=car.AddComponent<Rigidbody>();rb.isKinematic=true;rb.useGravity=false;rb.interpolation=RigidbodyInterpolation.Interpolate;var pc=car.AddComponent<PlayerCar>();pc.visual=visual;var glow=Mesh("Neon underbody",visual,new Vector3(0,.19f,0),new Vector3(1.8f,.05f,3.25f),cyan);pc.glowRenderer=glow.GetComponent<Renderer>();pc.underglow=Lamp("Speed Reactive Underglow",car.transform,new Vector3(0,.3f,0),Cyan,4,5);foreach(float x in new[]{-.6f,.6f}){var head=Lamp("Headlight Beam",visual,new Vector3(x,.75f,1.85f),new Color(.65f,.85f,1),20,42,LightType.Spot);head.spotAngle=48;head.innerSpotAngle=27;head.transform.localRotation=Quaternion.Euler(7,0,0);}
 pc.exhaust=Particle("Exhaust",visual,3,.45f,.16f,particleMat,true);pc.exhaust.transform.localPosition=new Vector3(0,.4f,-1.95f);var shape=pc.exhaust.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.angle=12;pc.exhaust.transform.localRotation=Quaternion.Euler(0,180,0);}
 return car;}
 static GameObject CreateRoad(){var road=Node("RoadSegment");road.AddComponent<PooledObject>();float len=settings.segmentLength;float half=settings.roadWidth*.5f;
 Mesh("Road surface",road.transform,new Vector3(0,-.17f,len*.5f),new Vector3(settings.roadWidth,.3f,len),asphalt,PrimitiveType.Cube,true);
 foreach(float side in new[]{-1f,1f}){Mesh("Shoulder",road.transform,new Vector3(side*(half+.9f),-.1f,len*.5f),new Vector3(1.8f,.4f,len),metal);Mesh("Guardrail",road.transform,new Vector3(side*(half+1.7f),.65f,len*.5f),new Vector3(.18f,.8f,len),metal);Mesh("Neon edge",road.transform,new Vector3(side*half,.025f,len*.5f),new Vector3(.1f,.04f,len),side<0?cyan:pink);
 for(int i=0;i<3;i++){float z=i*20+8;Mesh("Light pole",road.transform,new Vector3(side*(half+1.8f),4,z),new Vector3(.15f,8,.15f),metal);Mesh("Lamp arm",road.transform,new Vector3(side*(half+.7f),8,z),new Vector3(2.5f,.12f,.14f),metal);Mesh("Lamp glow",road.transform,new Vector3(side*(half-.3f),7.9f,z),new Vector3(1.1f,.1f,.4f),white); // baked-looking emissive fixtures plus sparse real light
 if(i==1){var l=Lamp("Streetlight",road.transform,new Vector3(side*(half-.3f),7.6f,z),new Color(.35f,.55f,1),8,18,LightType.Spot);l.spotAngle=110;l.transform.localRotation=Quaternion.Euler(90,0,0);}
 }
 // Give distant emissive strips enough screen coverage as the camera moves.
 var random=new System.Random(side<0?41:82);
 for(int i=0;i<5;i++)
 {
     float height=8+random.Next(22),x=side*(18+random.Next(25)),z=i*12;
     var neon=i%2==0?cyan:pink;
     Mesh("City tower",road.transform,new Vector3(x,height*.5f,z),new Vector3(5,height,7),black);
     Mesh("Tower accent",road.transform,new Vector3(x-side*2.55f,height*.5f,z-3.65f),new Vector3(.36f,height,.18f),neon);
     for(int w=2;w<height;w+=4)
         Mesh("Window ribbon",road.transform,new Vector3(x,w,z-3.65f),new Vector3(4,.48f,.18f),neon);
 }
 }
 foreach(float x in new[]{-settings.laneWidth*.5f,settings.laneWidth*.5f})for(int i=0;i<10;i++)Mesh("Lane dash",road.transform,new Vector3(x,.015f,i*6+2),new Vector3(.1f,.025f,3.2f),white);
 return road;}
 static void CreateScene(bool menu,GameObject playerPrefab,GameObject roadPrefab,GameObject stationary,GameObject moving,GameObject coin,GameObject fuel){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
 var system=Node("Game Systems");var gm=system.AddComponent<GameManager>();gm.settings=settings;gm.controls=input;gm.menuScene=menu;
 var pool=Node("Object Pools").AddComponent<PoolManager>();pool.entries=new[]{new PoolEntry{key="Road",prefab=roadPrefab,capacity=10},new PoolEntry{key="Stationary",prefab=stationary,capacity=24},new PoolEntry{key="Moving",prefab=moving,capacity=16},new PoolEntry{key="Coin",prefab=coin,capacity=48},new PoolEntry{key="Fuel",prefab=fuel,capacity=12}};gm.pools=pool;
 var player=(GameObject)PrefabUtility.InstantiatePrefab(playerPrefab);gm.player=player.GetComponent<PlayerCar>();
 var camGo=Node("Main Camera");camGo.tag="MainCamera";var camera=camGo.AddComponent<Camera>();camera.fieldOfView=65;camera.nearClipPlane=.1f;camera.farClipPlane=600;camera.allowHDR=true;camera.backgroundColor=new Color(.008f,.012f,.04f);camera.clearFlags=CameraClearFlags.Skybox;camGo.AddComponent<AudioListener>();var urp=camGo.AddComponent<UniversalAdditionalCameraData>();urp.renderPostProcessing=true;urp.antialiasing=AntialiasingMode.FastApproximateAntialiasing;var follow=camGo.AddComponent<FollowCamera>();follow.target=player.transform;gm.player.cameraRig=follow;follow.Snap();
 var road=Node("Procedural Highway").AddComponent<RoadGenerator>();road.pools=pool;road.settings=settings;road.player=gm.player;gm.road=road;
 RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.15f,.19f,.3f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.018f,.025f,.065f);RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.006f;
 var moon=Lamp("Moonlight",null,Vector3.zero,new Color(.4f,.55f,1),1,100,LightType.Directional);moon.transform.rotation=Quaternion.Euler(35,-25,0);
 CreateSky();var volume=Node("Global Bloom Volume").AddComponent<Volume>();volume.isGlobal=true;var vp=AssetDatabase.LoadAssetAtPath<VolumeProfile>(Root+"Settings/NightVolume.asset");if(!vp){vp=ScriptableObject.CreateInstance<VolumeProfile>();AssetDatabase.CreateAsset(vp,Root+"Settings/NightVolume.asset");var bloom=vp.Add<Bloom>();bloom.threshold.Override(.8f);bloom.intensity.Override(.75f);bloom.scatter.Override(.65f);var tone=vp.Add<Tonemapping>();tone.mode.Override(TonemappingMode.ACES);var vignette=vp.Add<Vignette>();vignette.intensity.Override(.23f);AssetDatabase.SaveAssets();}if(!vp.TryGet<Bloom>(out var savedBloom)){savedBloom=vp.Add<Bloom>();}savedBloom.threshold.Override(.8f);savedBloom.intensity.Override(.9f);savedBloom.scatter.Override(.65f);if(!vp.TryGet<Tonemapping>(out var savedTone)){savedTone=vp.Add<Tonemapping>();}savedTone.mode.Override(TonemappingMode.ACES);if(!vp.TryGet<Vignette>(out var savedVignette)){savedVignette=vp.Add<Vignette>();}savedVignette.intensity.Override(.2f);foreach(var component in vp.components){if(!AssetDatabase.Contains(component))AssetDatabase.AddObjectToAsset(component,vp);EditorUtility.SetDirty(component);}EditorUtility.SetDirty(vp);AssetDatabase.SaveAssets();volume.sharedProfile=vp;
 var effects=Node("Pooled VFX").AddComponent<EffectsDirector>();effects.player=player.transform;effects.bursts=Enumerable.Range(0,8).Select(i=>Particle("Pickup Impact "+i,effects.transform,5,.65f,.12f,particleMat)).ToArray();effects.launch=Particle("Fireworks Launch",effects.transform,20,1.2f,.16f,particleMat);var ls=effects.launch.shape;ls.shapeType=ParticleSystemShapeType.Cone;ls.angle=4;effects.launch.transform.rotation=Quaternion.Euler(-90,0,0);effects.firework=Particle("Fireworks Explosion",effects.transform,12,2.4f,.22f,particleMat);var fm=effects.firework.main;fm.gravityModifier=.25f;gm.effects=effects;
 var audio=Node("Audio Director").AddComponent<AudioDirector>();audio.musicSource=audio.gameObject.AddComponent<AudioSource>();audio.engineSource=audio.gameObject.AddComponent<AudioSource>();audio.effectSource=audio.gameObject.AddComponent<AudioSource>();foreach(var a in audio.GetComponents<AudioSource>())a.playOnAwake=false;audio.music=AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Music.wav");audio.engine=AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Engine.wav");audio.crash=AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Crash.wav");audio.coin=AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Coin.wav");audio.fuel=AssetDatabase.LoadAssetAtPath<AudioClip>(Root+"Audio/Fuel.wav");gm.audioDirector=audio;
 gm.ui=CreateUI(gm);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Root+"Scenes/"+(menu?"MainMenu":"Gameplay")+".unity");}
 static void CreateSky(){var sky=AssetDatabase.LoadAssetAtPath<Material>(Root+"Materials/NightSky.mat");if(!sky){const int w=1024,h=512;var tex=new Texture2D(w,h,TextureFormat.RGB24,false);var pixels=new Color[w*h];var rng=new System.Random(91);for(int y=0;y<h;y++)for(int x=0;x<w;x++){float v=(float)y/h;pixels[y*w+x]=Color.Lerp(new Color(.045f,.035f,.12f),new Color(.002f,.004f,.018f),v);}for(int i=0;i<1300;i++){int x=rng.Next(w),y=rng.Next(h/3,h);pixels[y*w+x]=new Color(.3f,.45f,.7f)*((float)rng.NextDouble()+.3f);}tex.SetPixels(pixels);tex.Apply();File.WriteAllBytes(Root+"Materials/Stars.png",tex.EncodeToPNG());AssetDatabase.ImportAsset(Root+"Materials/Stars.png");sky=new Material(Shader.Find("Skybox/Panoramic"));sky.SetTexture("_MainTex",AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Materials/Stars.png"));sky.SetFloat("_Exposure",.65f);AssetDatabase.CreateAsset(sky,Root+"Materials/NightSky.mat");UnityEngine.Object.DestroyImmediate(tex);}RenderSettings.skybox=sky;}
 static RectTransform Rect(GameObject go,Vector2 min,Vector2 max,Vector2 position,Vector2 size){var r=go.GetComponent<RectTransform>();if(!r)r=go.AddComponent<RectTransform>();r.anchorMin=min;r.anchorMax=max;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=position;r.sizeDelta=size;return r;}
 static GameObject Panel(string name,Transform parent,Color color){var g=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));g.transform.SetParent(parent,false);Rect(g,Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero);g.GetComponent<Image>().color=color;return g;}
 static TMP_Text Label(string name,Transform parent,string value,Vector2 pos,Vector2 size,float fontSize,Color color,Vector2? anchor=null){var g=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer));g.transform.SetParent(parent,false);var point=anchor??new Vector2(.5f,.5f);Rect(g,point,point,pos,size);var t=g.AddComponent<TextMeshProUGUI>();t.font=font;t.text=value;t.fontSize=fontSize;t.color=color;t.alignment=TextAlignmentOptions.Center;t.raycastTarget=false;return t;}
 static void Button(string text,Transform parent,Vector2 pos,UnityAction action){var g=new GameObject(text,typeof(RectTransform),typeof(CanvasRenderer),typeof(Image),typeof(Button));g.transform.SetParent(parent,false);Rect(g,new Vector2(.5f,.5f),new Vector2(.5f,.5f),pos,new Vector2(340,56));g.GetComponent<Image>().color=new Color(.035f,.11f,.19f,.97f);var b=g.GetComponent<Button>();var colors=b.colors;colors.highlightedColor=new Color(.2f,.85f,1);colors.selectedColor=colors.highlightedColor;colors.pressedColor=Pink;b.colors=colors;UnityEventTools.AddPersistentListener(b.onClick,action);Label("Label",g.transform,text,Vector2.zero,new Vector2(330,50),23,Color.white);var stripe=Panel("Accent",g.transform,Cyan);Rect(stripe,Vector2.zero,new Vector2(0,1),Vector2.zero,new Vector2(3,0));}
 static RunnerUI CreateUI(GameManager gm){var canvas=Node("Neon Interface");var c=canvas.AddComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;var scale=canvas.AddComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1600,900);scale.matchWidthOrHeight=.5f;canvas.AddComponent<GraphicRaycaster>();var ui=canvas.AddComponent<RunnerUI>();var eventSystem=Node("EventSystem");eventSystem.AddComponent<EventSystem>();eventSystem.AddComponent<InputSystemUIInputModule>();
 ui.hud=Panel("HUD",canvas.transform,Color.clear);ui.hud.GetComponent<Image>().raycastTarget=false;var top=Panel("Instrument Header",ui.hud.transform,new Color(.008f,.02f,.055f,.86f));Rect(top,new Vector2(0,1),Vector2.one,new Vector2(0,-60),new Vector2(0,120));
