 static void CreateAudio(){foreach(string name in new[]{"Engine","Crash","Coin","Fuel","Music"}){string path=Root+"Audio/"+name+".wav";if(File.Exists(path))continue;const int rate=22050;float duration=name=="Music"?16:name=="Engine"?2:name=="Crash"?.45f:.35f;int n=(int)(duration*rate);var samples=new short[n];var rng=new System.Random(42);double[] notes={110,130.8128,164.8138,146.8324,110,130.8128,195.9977,164.8138};for(int i=0;i<n;i++){double t=(double)i/rate,v=0;if(name=="Engine")v=(Math.Sin(t*Math.PI*2*55)+.4*Math.Sin(t*Math.PI*2*110)+.2*Math.Sin(t*Math.PI*2*165))*.2;
 else if(name=="Crash")v=(rng.NextDouble()*2-1)*Math.Exp(-t*10)*.7;
 else if(name=="Coin"||name=="Fuel"){double f=name=="Coin"?(t<.12?880:1320):(t<.12?440:t<.23?554:660);v=Math.Sin(t*Math.PI*2*f)*Math.Exp(-t*7)*.45;}
 else{int beat=(int)(t*2);double local=t*.0+(t*2-Math.Floor(t*2))*.5;double bass=notes[(beat/4)%8];v=Math.Sin(t*Math.PI*2*bass)*Math.Exp(-local*5)*.24+Math.Sin(t*Math.PI*2*bass*4)*Math.Exp(-local*15)*.1;if(beat%2==0)v+=Math.Sin(2*Math.PI*(55*local+8*(1-Math.Exp(-local*30))))*Math.Exp(-local*24)*.25;v+=(rng.NextDouble()*2-1)*Math.Exp(-local*70)*.04;}
 double edge=Math.Min(1,Math.Min(t*100,(duration-t)*100));samples[i]=(short)(Math.Clamp(v*edge,-1,1)*short.MaxValue);}
 using(var writer=new BinaryWriter(File.Create(path))){writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+n*2);writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(rate);writer.Write(rate*2);writer.Write((short)2);writer.Write((short)16);writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));writer.Write(n*2);foreach(short sample in samples)writer.Write(sample);}AssetDatabase.ImportAsset(path);}}
